/*
 * A080606  Golomb's sequence using even integers.
 * https://oeis.org/A080606
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = 2,2,4,4,6,6,6,6,8,8,8,8,10,10,... The sequence is
 *            generated by letting the even integer 2k appear a(k) times,
 *            where a(k) is the term at index k. The implementation produces
 *            the terms in O(n) time by keeping track of the current block
 *            (even integer) and how many positions remain in that block
 * Range:     u8 n <= 2876, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   seq_alloc_new_array
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>                 /* size_t */
#include <stdlib.h>                 /* malloc, free */
#include "../utils/seq_alloc_new_array.h"

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;   /* undefined for 0, but avoid UB */

    /* Allocate space for the terms up to n (1‑based). */
    seq_t *seq = seq_alloc_new_array((size_t)n + 1);
    if (!seq) return (seq_t)0;     /* allocation failure – return 0 */

    seq_t current_value = 2;       /* 2 * current block index */
    idx_t  block_index  = 1;       /* current block number (k) */
    seq_t  remaining    = 0;       /* remaining positions in current block */

    for (idx_t idx = 1; idx <= n; ++idx) {
        seq[idx] = current_value;         /* set a(idx) */

        if (remaining == 0) {
            /* start (or restart) the block: the block length
               equals the value already stored at a[block_index] */
            remaining = seq[block_index];
        }
        --remaining;

        if (remaining == 0) {
            /* finished the block, move to the next one */
            ++block_index;
            current_value = 2 * (seq_t)block_index;
        }
    }

    seq_t result = seq[n];
    free(seq);
    return result;
}
